b='''    private static float[] buildRawScalarFixedD65Neutral(\n            CameraCharacteristics characteristics) throws Exception {\n        if (characteristics == null) {\n            throw new IllegalStateException("RAWSCALAR1B requires physical CameraCharacteristics");\n        }\n        Integer ref1Obj = characteristics.get(CameraCharacteristics.SENSOR_REFERENCE_ILLUMINANT1);\n        Byte ref2Obj = characteristics.get(CameraCharacteristics.SENSOR_REFERENCE_ILLUMINANT2);\n        if (ref1Obj == null || ref2Obj == null) {\n            throw new IllegalStateException("RAWSCALAR1B missing reference illuminants");\n        }\n        ColorSpaceTransform calT;\n        ColorSpaceTransform cmT;\n        if (ref1Obj == 21) {\n            calT = characteristics.get(CameraCharacteristics.SENSOR_CALIBRATION_TRANSFORM1);\n            cmT = characteristics.get(CameraCharacteristics.SENSOR_COLOR_TRANSFORM1);\n        } else if (((int) ref2Obj) == 21) {\n            calT = characteristics.get(CameraCharacteristics.SENSOR_CALIBRATION_TRANSFORM2);\n            cmT = characteristics.get(CameraCharacteristics.SENSOR_COLOR_TRANSFORM2);\n        } else {\n            throw new IllegalStateException("RAWSCALAR1B requires an exact D65 (21) camera calibration anchor");\n        }\n        float[] cal = nativeProspectiveTransform(calT);\n        float[] cm = nativeProspectiveTransform(cmT);\n        if (!nativeProspectiveValid3x3(cal) || !nativeProspectiveValid3x3(cm)) {\n            throw new IllegalStateException("RAWSCALAR1B invalid D65 calibration/color transform");\n        }\n        double[] xyzToCamera = matMul3(nativeProspectiveDouble(cal), nativeProspectiveDouble(cm));\n        double[] cameraWhite = matVec3(xyzToCamera, xyToXyz(D65_XY));\n        double g = cameraWhite[1];\n        if (!Double.isFinite(cameraWhite[0]) || !Double.isFinite(g) || !Double.isFinite(cameraWhite[2])\n                || cameraWhite[0] <= 0.0 || g <= 0.0 || cameraWhite[2] <= 0.0) {\n            throw new IllegalStateException("RAWSCALAR1B invalid D65 camera white");\n        }\n        float r = (float)(cameraWhite[0] / g);\n        float b = (float)(cameraWhite[2] / g);\n        if (!Float.isFinite(r) || !Float.isFinite(b) || r <= 0.0f || b <= 0.0f) {\n            throw new IllegalStateException("RAWSCALAR1B invalid normalized D65 neutral");\n        }\n        return new float[]{r, 1.0f, b};\n    }\n\n    private static NativeProspectiveSource buildNativeProspectiveSource(\n            CameraCharacteristics characteristics,\n            CaptureResult captureResult) throws Exception {\n'''
